// Segredo compartilhado com o Worker do Cloudflare (env N8N_NOTION_WEBHOOK_SECRET).
// Troque 'TROQUE_PELO_SEGREDO' pelo mesmo valor configurado no Worker.
const SECRET = 'TROQUE_PELO_SEGREDO';

const item = $input.first().json || {};
const headers = item.headers || {};

const headerName = Object.keys(headers).find((k) => k.toLowerCase() === 'x-radar-secret');
if (!headerName || headers[headerName] !== SECRET) {
  throw new Error('x-radar-secret invalido ou ausente');
}

const b = item.body || item;

return [{
  json: {
    titulo: (b.titulo && String(b.titulo).trim()) || 'Sem título',
    o_que_disse: b.o_que_disse ?? '',
    area: b.area ?? '',
    precisa_retorno: b.precisa_retorno ?? '',
    responsavel: b.responsavel ?? '',
    pessoa: b.pessoa ?? '',
    telefone: b.telefone ?? '',
    data: b.data ?? '',
    urgencia: b.urgencia ?? '',
    o_que_fizemos: b.o_que_fizemos ?? '',
    status: b.status ?? '',
    fonte: b.fonte ?? '',
    cidade: b.cidade ?? '',
    cidade_page_id: (b.cidade_page_id && String(b.cidade_page_id).trim()) || '',
    sessao: b.sessao ?? '',
    responsavel_notion_id: (b.responsavel_notion_id && String(b.responsavel_notion_id).trim()) || '',
  },
}];

// Monta o body cru da API do Notion (POST /v1/pages) a partir do form normalizado.
// A relation "Cidade" recebe o page id do município na database "Cidade x Macrorregião"
// (3a7b2502-d314-800e-94bf-ff26770e5945); a property "Macrorregião" do Radar é um ROLLUP
// sobre essa relation e preenche sozinha — por isso NÃO é enviada aqui.
// "Responsável pelo contato" (people) é setado aqui mesmo quando o id existe.

const DATABASE_ID = 'SELECIONE_DATABASE_NOTION';
const p = $json;
const props = {};

props['O que chegou'] = { title: [{ text: { content: p.titulo } }] };

if (p.o_que_disse) props['O que a pessoa disse'] = { rich_text: [{ text: { content: p.o_que_disse } }] };
if (p.area) props['Área'] = { select: { name: p.area } };
if (p.precisa_retorno) props['Precisa de retorno'] = { select: { name: p.precisa_retorno } };
if (p.pessoa) props['Pessoa'] = { rich_text: [{ text: { content: p.pessoa } }] };
if (p.telefone) props['Telefone'] = { phone_number: p.telefone };
if (p.data) props['Data'] = { date: { start: p.data } };
if (p.urgencia) props['Urgência'] = { select: { name: p.urgencia } };
if (p.o_que_fizemos) props['O que a gente fez'] = { rich_text: [{ text: { content: p.o_que_fizemos } }] };
if (p.status) props['Status'] = { select: { name: p.status } };
if (p.fonte) props['Fonte'] = { select: { name: p.fonte } };
if (p.sessao) props['Sessão responsável pelo contato'] = { rich_text: [{ text: { content: p.sessao } }] };
if (p.cidade_page_id) props['Cidade'] = { relation: [{ id: p.cidade_page_id }] };
if (p.responsavel_notion_id) props['Responsável pelo contato'] = { people: [{ id: p.responsavel_notion_id }] };

return [{
  json: {
    parent: { database_id: DATABASE_ID },
    properties: props,
  },
}];
